import math

def is_octagonal(n):
    if n < 1:
        return False
    discriminant = 4 + 12 * n
    sqrt_disc = math.isqrt(discriminant)
    if sqrt_disc * sqrt_disc != discriminant:
        return False
    numerator = 2 + sqrt_disc
    if numerator % 6 != 0:
        return False
    k = numerator // 6
    return k >= 1 and k * (3 * k - 2) == n

