def find_solution(a, b, n):
    # Handle edge cases where a or b is zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        # equation: 0*x + b*y = n => b*y = n
        if n % b == 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # equation: a*x + 0*y = n => a*x = n
        if n % a == 0:
            return (n // a, 0)
        else:
            return None

    # Compute gcd and coefficients for |a| and |b|
    a_abs, b_abs = abs(a), abs(b)

    # Iterative extended Euclidean algorithm
    old_r, r = a_abs, b_abs
    old_s, s = 1, 0
    old_t, t = 0, 1

    while r != 0:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s
        old_t, t = t, old_t - quotient * t

    # Now old_r is gcd(a_abs, b_abs)
    g = old_r
    x0, y0 = old_s, old_t  # so a_abs*x0 + b_abs*y0 = g

    # Adjust signs to satisfy a*x + b*y = g
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # Check if solution exists
    if n % g != 0:
        return None

    # Scale the solution
    factor = n // g
    return (x0 * factor, y0 * factor)

