def newman_prime(n):
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    # NSW sequence: S0 = 1, S1 = 1, S_k = 2*S_{k-1} + S_{k-2}
    s_prev2 = 1  # S0
    s_prev1 = 1  # S1
    count = 0

    # Check S0 and S1
    if is_prime(s_prev2):
        count += 1
        if count == n:
            return s_prev2
    if is_prime(s_prev1):
        count += 1
        if count == n:
            return s_prev1

    # Generate S2, S3, ... until we find n-th prime
    k = 2
    while True:
        s_curr = 2 * s_prev1 + s_prev2
        if is_prime(s_curr):
            count += 1
            if count == n:
                return s_curr
        # Advance the recurrence
        s_prev2, s_prev1 = s_prev1, s_curr
        k += 1

