def newman_prime(n):
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        # Check odd factors up to sqrt(x)
        limit = math.isqrt(x)
        i = 3
        while i <= limit:
            if x % i == 0:
                return False
            i += 2
        return True

    # NSW sequence: S0 = 1, S1 = 1, S_k = 2*S_{k-1} + S_{k-2}
    a, b = 1, 1  # S0, S1
    count = 0

    # Generate NSW numbers starting from S2
    while True:
        c = 2 * b + a  # S_k for k >= 2
        if is_prime(c):
            count += 1
            if count == n:
                return c
        a, b = b, c

