def set_left_most_unset_bit(n):
    if n == 0:
        return 1
    b = n.bit_length()
    # Check from the most significant bit (b-1) down to 0
    for i in range(b - 1, -1, -1):
        if (n & (1 << i)) == 0:
            return n | (1 << i)
    # All bits from 0 to b-1 are set, so the leftmost unset bit is at position b
    return n | (1 << b)

