def set_left_most_unset_bit(n):
    if n == 0:
        return 1
    bit_len = n.bit_length()
    # Check if n is all ones in 'bit_len' bits
    if n == (1 << bit_len) - 1:
        return n | (1 << bit_len)
    # Find the leftmost unset bit from the highest bit downwards
    for i in range(bit_len - 1, -1, -1):
        if n & (1 << i) == 0:
            return n | (1 << i)
    # This line should never be reached, but included for safety
    return n | (1 << bit_len)

