def cal_sum(n):
    if n < 0:
        return 0
    if n == 0:
        return 3
    if n == 1:
        return 3  # P(0) + P(1) = 3 + 0
    if n == 2:
        return 5  # P(0) + P(1) + P(2) = 3 + 0 + 2

    # Initialize for P(0), P(1), P(2)
    a, b, c = 3, 0, 2
    total = 3 + 0 + 2  # sum of P(0) to P(2)

    # Compute and add P(3) through P(n) inclusive
    for i in range(3, n + 1):
        next_val = a + b  # P(i) = P(i-3) + P(i-2)
        total += next_val
        # shift window: (P(i-3), P(i-2), P(i-1)) -> (P(i-2), P(i-1), P(i))
        a, b, c = b, c, next_val

    return total

