from collections import Counter

def tuple_intersection(test_list1, test_list2):
    def canonical(t):
        return tuple(sorted(t))

    canon_list1 = [canonical(t) for t in test_list1]
    canon_list2 = [canonical(t) for t in test_list2]

    counter1 = Counter(canon_list1)
    counter2 = Counter(canon_list2)

    # Multiset intersection: min count for each key
    intersection_counter = counter1 & counter2

    # Build result list: each canonical tuple repeated its intersection count
    result = []
    for tup, count in intersection_counter.items():
        result.extend([tup] * count)

    # Sort for deterministic output (since Counter iteration order is insertion-order, but we want consistent order across runs)
    return sorted(result)

