def cal_sum(n):
    if n <= 0:
        return 0
    # Initial Perrin numbers: P(0)=3, P(1)=0, P(2)=2
    p0, p1, p2 = 3, 0, 2
    total = 0

    for i in range(n):
        if i == 0:
            term = p0
        elif i == 1:
            term = p1
        elif i == 2:
            term = p2
        else:
            term = p0 + p1  # P(i) = P(i-3) + P(i-2)

        total += term

        # Update the sliding window for next iteration (only meaningful when i >= 2)
        if i >= 2:
            p0, p1, p2 = p1, p2, term

    return total

def cal_sum(n):
    if n <= 0:
        return 0
    a, b, c = 3, 0, 2  # P0, P1, P2
    total = 0
    for i in range(n):
        if i == 0:
            term = a
        elif i == 1:
            term = b
        elif i == 2:
            term = c
        else:
            term = a + b
            a, b, c = b, c, term
        total += term
    return total

import re

def find_adverb_position(text):
    # Safe exception list: common -ly words that are NOT adverbs (nouns/adjectives)
    exceptions = {
        'early', 'only', 'lonely', 'friendly', 'lovely', 'daily', 'silly',
        'jolly', 'holy', 'ugly', 'ally', 'family', 'baby', 'lily', 'melody',
        'jealousy', 'therapy', 'discovery', 'victory', 'memory', 'library',
        'gallery', 'mercenary', 'notary', 'testimony', 'adversary', 'legendary',
        'revolutionary', 'temporary', 'complimentary', 'subsidiary', 'sedimentary',
        'military', 'voluntary', 'elementary', 'extraordinary', 'ordinary',
        'necessary', 'secondary', 'primary', 'tertiary', 'supplementary',
        'complementary', 'contemporary', 'controversial'
    }

    # First: look for -ly adverbs
    for match in re.finditer(r'\b([a-zA-Z]+ly)\b', text, re.IGNORECASE):
        word = match.group(1).lower()
        if word not in exceptions and len(word) >= 4:  # exclude very short ones like 'ly' (invalid)
            return (match.group(1), match.start(1), match.end(1))

    # Second: check for 'well' (common non-ly adverb)
    for match in re.finditer(r'\bwell\b', text, re.IGNORECASE):
        return ('well', match.start(), match.end())

    return None

