        'contemporary', 'controversial', 'elementary', 'extraordinary', 'ordinary',
        'necessary', 'secondary', 'primary', 'tertiary', 'military', 'voluntary'
    }

    # First, find -ly adverbs
    for match in re.finditer(r'\b[a-zA-Z]+ly\b', text, re.IGNORECASE):
